GAME_HTML = '<!DOCTYPE html><html lang="ko"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>\n*{box-sizing:border-box}body{margin:0;background:#101b20;color:#e8efe8;font-family:system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:16px}header{display:flex;align-items:center;justify-content:space-between;gap:8px}h1{font-size:25px;margin:4px 0}small,.muted{color:#a4b5ac}button,.file{border:1px solid #42524d;border-radius:10px;background:#22352f;color:#f2f5ed;padding:12px;cursor:pointer;font-weight:700;touch-action:manipulation}button:hover{background:#354f40}button:disabled{opacity:.45;cursor:default}.gold{background:#e5bc62;color:#252a20;border:0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:16px 0}.stat{background:#1c2c2c;border:1px solid #344641;border-radius:12px;padding:12px}.stat span{display:block;color:#9fb5ac;font-size:12px}.stat b{font-size:21px}#world{position:relative;border:1px solid #42524d;border-radius:14px;overflow:hidden}canvas{image-rendering:pixelated;display:block;width:100%;height:380px;touch-action:none;outline:none}#tip{min-height:43px;padding:12px;background:#20332d;font-size:14px;border-radius:9px;margin:10px 0}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button{flex:1}.controls{display:flex;justify-content:space-between;gap:12px;margin-top:12px}.pad{display:grid;grid-template-columns:repeat(3,52px);gap:5px}.pad button{padding:14px}.mine{width:120px;background:#cba855;color:#1c261f;font-size:18px}dialog{max-height:85vh;overflow-y:auto;background:#172a28;color:#eef3e9;border:1px solid #6b806e;border-radius:16px;max-width:440px;width:92%;padding:24px}dialog::backdrop{background:#000a}dialog h2{margin-top:0}.row{padding:15px 0;border-bottom:1px solid #3a4b43}.row button{width:100%;margin-top:8px}footer{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0;font-size:12px}.close{float:right;padding:6px 12px}.help{line-height:1.8;font-size:13px}input[type=file]{display:none}@media(max-width:500px){main{padding:8px}h1{font-size:20px}.stat{padding:9px}.stat b{font-size:17px}canvas{height:330px}header small{font-size:10px}.actions button{font-size:12px;padding:12px 7px}}\n</style><main><header><div><small>GOLDROOT · 작은 광산 마을</small><h1>황금빛 지하로</h1></div><small id="saveState">자동 저장 준비</small></header><div class="stats"><div class="stat"><span>보유 코인</span><b id="coins">0</b></div><div class="stat"><span>강화용 금</span><b id="gold">0</b></div><div class="stat"><span>돌 / 가방</span><b id="bag">0 / 30</b></div><div class="stat"><span>현재 위치</span><b id="depth">지상</b></div></div><div id="world"><canvas id="canvas" tabindex="0" aria-label="광산 게임. 방향키로 이동하고 스페이스로 채굴하세요."></canvas></div><div id="tip" role="status">광산 입구로 걸어가서 ‘이용하기’를 누르세요.</div><div id="business" class="muted" style="padding:8px 0;font-size:13px"></div><div class="actions"><button class="gold" id="interact">이용하기 · E</button><button id="return">지상으로 귀환</button><button id="newMine">광맥 새로 찾기</button></div><div class="actions" style="margin-top:8px"><button id="manage">🏭 광산 경영</button><button id="orders">📦 납품 주문</button><button id="goals">🏆 목표 / 업적</button></div><div class="controls"><div class="pad"><div></div><button data-dir="up">▲</button><div></div><button data-dir="left">◀</button><button data-dir="down">▼</button><button data-dir="right">▶</button></div><button id="mine" class="mine">⛏ 채굴<br><small style="color:#48543e">길게 누르기</small></button></div><div class="help muted">방향키 / WASD 이동 · Space 채굴 · E 시설 이용<br>돌은 상점에서 코인으로, 금은 훈련소에서 채굴 스킬 강화에 사용하세요. 광석 바로 옆에서 광석을 바라보고 채굴하세요.</div><footer><button id="export">저장 파일 받기</button><label class="file">저장 불러오기<input id="import" type="file" accept=".json"></label><button id="reset">새 게임</button></footer></main><dialog id="panel"><button class="close" id="close">닫기</button><h2 id="panelTitle"></h2><div id="panelBody"></div></dialog><script>\n\'use strict\';\nconst $=id=>document.getElementById(id), canvas=$(\'canvas\'),ctx=canvas.getContext(\'2d\');\nconst W=19,H=15,KEY=\'goldroot-save-v1\',directions={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};\nlet state,held={},lastStep=0,lastMine=0,walk=0,swing=0,particles=[],saveTimer=0;\nfunction fresh(){return {v:1,coins:0,gold:0,stone:0,pick:1,skill:1,bag:1,floor:1,zone:\'surface\',x:9,y:9,dir:\'down\',map:[],mined:0};}\nfunction capacity(){return 20+state.bag*10}function power(){return state.pick+state.skill-1}\nfunction newMap(){let a=[];for(let y=0;y<H;y++)for(let x=0;x<W;x++){let border=x===0||y===0||x===W-1||y===H-1;let empty=(x===9||y===2||y===7||y===12);let gold=(x===8&&y===3)||Math.random()<.18;let type=border?3:empty?0:gold?2:1;let hp=type===2?5+state.floor*2:2+state.floor;a.push({type,hp,max:hp});}return a;}\nfunction message(t){$(\'tip\').textContent=t}\nfunction save(){try{localStorage.setItem(KEY,JSON.stringify(state));$(\'saveState\').textContent=\'✓ 이 브라우저에 저장됨\'}catch(e){$(\'saveState\').textContent=\'저장 파일로 보관하세요\'}}\nfunction valid(s){const int=(n,a,b)=>Number.isInteger(n)&&n>=a&&n<=b;if(!s||s.v!==1||![\'surface\',\'mine\'].includes(s.zone)||!Object.hasOwn(directions,s.dir))return false;for(const k of [\'coins\',\'gold\',\'stone\',\'mined\'])if(!int(s[k],0,1e9))return false;for(const k of [\'pick\',\'skill\',\'bag\',\'floor\'])if(!int(s[k],1,1000))return false;if(s.stone>20+s.bag*10||!int(s.x,1,W-2)||!int(s.y,1,H-2)||!Array.isArray(s.map))return false;if(s.map.length!==0&&s.map.length!==W*H)return false;for(const c of s.map)if(!c||!int(c.type,0,3)||!int(c.max,1,10000)||!int(c.hp,0,c.max))return false;return s.zone!==\'mine\'||(s.map.length===W*H&&s.map[s.y*W+s.x].type===0);}\ntry{const loaded=JSON.parse(localStorage.getItem(KEY));state=valid(loaded)?loaded:fresh()}catch(e){state=fresh()}\nfunction hud(){$(\'coins\').textContent=state.coins.toLocaleString();$(\'gold\').textContent=state.gold.toLocaleString();$(\'bag\').textContent=state.stone+\' / \'+capacity();$(\'depth\').textContent=state.zone===\'mine\'?\'지하 \'+state.floor+\'층\':\'지상\';$(\'return\').disabled=state.zone===\'surface\';$(\'newMine\').disabled=state.zone===\'surface\';}\nfunction move(dir){state.dir=dir;const [dx,dy]=directions[dir],x=state.x+dx,y=state.y+dy;if(x<1||x>=W-1||y<1||y>=H-1)return;if(state.zone===\'mine\'&&state.map[y*W+x].type)return;state.x=x;state.y=y;walk=1;hud();}\nfunction mine(){if(state.zone!==\'mine\'){message(\'지하 광산에서 광석을 캘 수 있어요.\');return}const[dx,dy]=directions[state.dir],x=state.x+dx,y=state.y+dy,c=state.map[y*W+x];swing=1;if(!c||c.type===0||c.type===3){message(\'광석 옆에서 광석 쪽을 바라보세요.\');return}if(c.type===1&&state.stone>=capacity()){message(\'돌 가방이 가득 찼어요! 지상 상점에서 판매하세요.\');return}c.hp=Math.max(0,c.hp-power());for(let i=0;i<7;i++)particles.push({x:x+.5,y:y+.5,dx:(Math.random()-.5)*2,dy:-Math.random()*2,life:1,color:c.type===2?\'#f1cf6c\':\'#9caaa4\'});if(c.hp===0){if(c.type===2){const n=1+Math.floor(state.floor/3);state.gold+=n;message(\'금 +\'+n+\'! 지상 훈련소에서 스킬을 강화하세요.\')}else{state.stone++;message(\'돌 +1 · 상점 판매 가격: 개당 3코인\')}c.type=0;state.mined++;save()}hud();}\nconst facilities=[{x:4,y:5,name:\'돌 판매소\',color:\'#76c6a0\',kind:\'shop\'},{x:9,y:5,name:\'광산 입구\',color:\'#e6bc65\',kind:\'entrance\'},{x:14,y:5,name:\'훈련소\',color:\'#acaae6\',kind:\'skills\'},{x:5,y:11,name:\'광산 사무소\',color:\'#86bad1\',kind:\'manage\'},{x:13,y:11,name:\'주문 게시판\',color:\'#e9a5b4\',kind:\'orders\'}];\nfunction interact(){if(state.zone===\'mine\'){if(Math.abs(state.x-9)+Math.abs(state.y-2)<=1){surface()}else message(\'채굴은 Space 또는 채굴 버튼! 귀환 버튼으로 언제든 돌아갈 수 있어요.\');return}const f=facilities.find(f=>Math.abs(state.x-f.x)+Math.abs(state.y-f.y)<=2);if(!f){message(\'시설 간판 가까이 이동한 뒤 이용하기를 누르세요.\');return}if(f.kind===\'entrance\'){if(!state.map.length)state.map=newMap();state.zone=\'mine\';state.x=9;state.y=2;state.dir=\'down\';message(\'노란 광석은 금, 회색 광석은 돌이에요. 길을 파며 탐험하세요.\');save();hud()}else openPanel(f.kind);}\nfunction surface(){state.zone=\'surface\';state.x=9;state.y=7;message(\'지상에 도착했어요. 왼쪽은 돌 판매소, 오른쪽은 훈련소예요.\');save();hud()}\nlet panelKind=\'\';function cost(kind){return kind===\'skill\'?state.skill*4:kind===\'pick\'?state.pick*25:state.bag*20}\nfunction buy(kind){const money=kind===\'skill\'?\'gold\':\'coins\',price=cost(kind);if(state[kind]>=1000||state[money]<price)return;state[money]-=price;state[kind]++;save();hud();openPanel(panelKind);}\nfunction openPanel(kind){panelKind=kind;$(\'panelTitle\').textContent=kind===\'shop\'?\'돌 판매소\':\'채굴 훈련소\';let b=$(\'panelBody\');b.replaceChildren();const text=document.createElement(\'p\');text.textContent=kind===\'shop\'?\'돌은 개당 3코인에 매입합니다.\':\'금으로 채굴 숙련도를 올려보세요. 스킬 트리는 다음 업데이트에 추가해요.\';b.append(text);function row(title,label,fn,disabled=false){const r=document.createElement(\'div\');r.className=\'row\';const p=document.createElement(\'div\');p.textContent=title;const btn=document.createElement(\'button\');btn.textContent=label;btn.disabled=disabled;btn.onclick=fn;r.append(p,btn);b.append(r)}if(kind===\'shop\'){row(\'보유 돌 \'+state.stone+\'개\',\'전부 판매 · +\'+state.stone*3+\'코인\',()=>{state.coins+=state.stone*3;state.stone=0;save();hud();openPanel(kind)},!state.stone);row(\'곡괭이 Lv.\'+state.pick+\' · 채굴 피해 +1\',cost(\'pick\')+\'코인으로 강화\',()=>buy(\'pick\'),state.coins<cost(\'pick\'));row(\'가방 \'+capacity()+\'칸 · 용량 +10\',cost(\'bag\')+\'코인으로 확장\',()=>buy(\'bag\'),state.coins<cost(\'bag\'));}else{row(\'채굴 숙련 Lv.\'+state.skill+\' · 채굴 피해 +1\',cost(\'skill\')+\'금으로 강화\',()=>buy(\'skill\'),state.gold<cost(\'skill\'));row(\'현재 총 채굴 피해: \'+power(),\'확인\',()=>closePanel());}if(!$(\'panel\').open)$(\'panel\').showModal();held={};}\nfunction closePanel(){$(\'panel\').close();canvas.focus()}\n$(\'close\').onclick=closePanel;$(\'interact\').onclick=interact;$(\'return\').onclick=surface;$(\'newMine\').onclick=()=>{if(state.zone!==\'mine\')return;if(!confirm(\'남은 광석을 버리고 다음 층으로 이동할까요? 더 단단한 광석과 더 많은 금이 나옵니다.\'))return;if(state.floor>=1000)return;state.floor++;state.map=newMap();state.x=9;state.y=2;save();hud();message(\'새 광맥 발견! 지하 \'+state.floor+\'층입니다.\')};\nfunction bindHold(el,key){el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);held[key]=true;if(key===\'mine\'){mine();lastMine=performance.now()}else{move(key);lastStep=performance.now()}};el.onpointerup=el.onpointercancel=el.onlostpointercapture=()=>{delete held[key]};}\ndocument.querySelectorAll(\'[data-dir]\').forEach(b=>bindHold(b,b.dataset.dir));bindHold($(\'mine\'),\'mine\');const keys={ArrowUp:\'up\',w:\'up\',ArrowDown:\'down\',s:\'down\',ArrowLeft:\'left\',a:\'left\',ArrowRight:\'right\',d:\'right\',\' \':\'mine\'};window.addEventListener(\'keydown\',e=>{if($(\'panel\').open)return;const k=keys[e.key]||keys[e.key.toLowerCase()];if(k){e.preventDefault();held[k]=true}if(e.key.toLowerCase()===\'e\'&&!e.repeat)interact()});window.addEventListener(\'keyup\',e=>delete held[keys[e.key]||keys[e.key.toLowerCase()]]);window.addEventListener(\'blur\',()=>{held={};save()});document.addEventListener(\'visibilitychange\',()=>{if(document.hidden){held={};save()}});\n$(\'export\').onclick=()=>{save();const a=document.createElement(\'a\'),url=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:\'application/json\'}));a.href=url;a.download=\'goldroot-save.json\';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};\n$(\'import\').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>200000)throw Error();const data=JSON.parse(await file.text());if(!valid(data))throw Error();state=data;save();hud();message(\'저장한 광산을 불러왔어요.\')}catch(err){message(\'올바른 GOLDROOT 저장 파일이 아닙니다.\')}e.target.value=\'\'};\n$(\'reset\').onclick=()=>{if(confirm(\'진행 상황을 지우고 새 게임을 시작할까요?\')){state=fresh();save();hud();message(\'새 광산 이야기를 시작해 볼까요?\')}};\nfunction rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}function label(t,x,y,color=\'#dcebe0\',size=12){ctx.fillStyle=color;ctx.font=\'600 \'+size+\'px system-ui\';ctx.textAlign=\'center\';ctx.fillText(t,x,y)}\nlet prev=0;function frame(now){const dt=Math.min((now-prev)/1000,.05);prev=now;if(!$(\'panel\').open){if(now-lastStep>125){for(const d of [\'up\',\'down\',\'left\',\'right\'])if(held[d]){move(d);lastStep=now;break}}if(held.mine&&now-lastMine>300){mine();lastMine=now}}if(now-saveTimer>4000){save();saveTimer=now}swing=Math.max(0,swing-dt*5);walk=Math.max(0,walk-dt*6);const width=canvas.clientWidth,height=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(width*dpr)||canvas.height!==Math.round(height*dpr)){canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);rect(0,0,width,height,\'#111e23\');const tile=width<550?34:40,ox=width/2-(state.x+.5)*tile,oy=height/2-(state.y+.5)*tile;ctx.save();ctx.translate(ox,oy);\nfor(let y=0;y<H;y++)for(let x=0;x<W;x++){const px=x*tile,py=y*tile;if(state.zone===\'surface\'){rect(px,py,tile,tile,(x+y)%2?\'#2c493d\':\'#2e4c3e\');if(y>=7&&y<=9||x===9)rect(px,py,tile,tile,\'#6c6951\');else{rect(px+6,py+12,3,5,\'#507150\');rect(px+22,py+24,2,4,\'#496b48\')}}else{const c=state.map[y*W+x];rect(px,py,tile,tile,\'#1d282c\');if(c.type){rect(px+1,py+1,tile-2,tile-2,c.type===3?\'#151e25\':c.type===2?\'#65543a\':\'#435051\');rect(px+3,py+3,tile-6,3,c.type===2?\'#988054\':\'#64706c\');rect(px+tile-5,py+6,3,tile-8,\'#293638\');if(c.type===2){rect(px+8,py+10,7,6,\'#f3cf6d\');rect(px+21,py+20,6,8,\'#dba949\');rect(px+15,py+26,4,4,\'#fff1ad\')}else if(c.type===1){rect(px+9,py+14,8,3,\'#85918a\');rect(px+22,py+23,5,3,\'#637774\')}if(c.hp<c.max){rect(px+4,py+tile-7,tile-8,3,\'#182423\');rect(px+4,py+tile-7,(tile-8)*c.hp/c.max,3,\'#e5c467\')}}}}\nif(state.zone===\'surface\'){for(const f of facilities){const x=f.x*tile,y=f.y*tile;rect(x-tile*.8,y-tile*.7,tile*2.6,tile*1.5,\'#172c2c\');rect(x-tile,y-tile*.8,tile*3,tile*.25,f.color);rect(x+tile*.25,y+tile*.15,tile*.5,tile*.65,\'#0d1c20\');rect(x-tile*.5,y,tile*.5,tile*.35,f.color);label(f.name,x+tile/2,y-tile, \'#f3edd2\',13);}}else{const x=9*tile,y=2*tile;rect(x+9,y,4,tile,\'#c7a979\');rect(x+tile-13,y,4,tile,\'#c7a979\');for(let i=4;i<tile;i+=9)rect(x+9,y+i,tile-18,3,\'#e7c790\');label(\'출구\',x+tile/2,y-8,\'#d9ca9d\')}\nconst px=(state.x+.5)*tile,py=(state.y+.5)*tile;drawMiner(px,py,now,state.dir,walk,swing);const [dx,dy]=directions[state.dir];ctx.strokeStyle=\'#f2d888\';ctx.lineWidth=2;ctx.strokeRect((state.x+dx)*tile+2,(state.y+dy)*tile+2,tile-4,tile-4);\nparticles=particles.filter(p=>p.life>0);for(const p of particles){p.life-=dt*2;p.x+=p.dx*dt;p.y+=p.dy*dt;p.dy+=dt*7;rect(p.x*tile,p.y*tile,4,4,p.color)}drawBusiness(tile,now);ctx.restore();if(state.zone===\'mine\'){const grad=ctx.createRadialGradient(width/2,height/2,60,width/2,height/2,width*.7);grad.addColorStop(0,\'#0000\');grad.addColorStop(1,\'#040a16aa\');ctx.fillStyle=grad;ctx.fillRect(0,0,width,height)}label(state.zone===\'mine\'?\'UNDERGROUND / B\'+state.floor:\'GOLDROOT VILLAGE\',width/2,25,\'#e1d9b8\',11);requestAnimationFrame(frame)}\n// v0.2: original assets and game systems; no external files required.\nconst baseFresh=fresh,baseValid=valid,baseSave=save,baseHud=hud,basePanel=openPanel;\nconst extraDefaults=()=>({workers:0,workshop:0,warehouse:0,manager:0,raw:0,bricks:0,produced:0,sold:0,ordersDone:0,claimed:[],lastTick:Date.now(),workerTimer:0,factoryTimer:0});\nfresh=function(){return {...baseFresh(),...extraDefaults()}};\nfunction migrate(s){const d=extraDefaults();for(const k in d)if(s[k]===undefined)s[k]=d[k];return s}\nvalid=function(s){if(!baseValid(s))return false;for(const k of [\'workers\',\'workshop\',\'warehouse\',\'manager\',\'raw\',\'bricks\',\'produced\',\'sold\',\'ordersDone\',\'workerTimer\',\'factoryTimer\',\'lastTick\'])if(s[k]!==undefined&&(!Number.isSafeInteger(s[k])||s[k]<0))return false;if((s.workers??0)>20||(s.workshop??0)>10||(s.warehouse??0)>10||(s.manager??0)>1||(s.raw??0)>1100||(s.workerTimer??0)>7||(s.factoryTimer??0)>19||(s.ordersDone??0)>1e6||(s.lastTick??0)>Date.now()+300000)return false;return s.claimed===undefined||(Array.isArray(s.claimed)&&s.claimed.length<=10&&s.claimed.every(n=>Number.isInteger(n)&&n>=0&&n<6)&&new Set(s.claimed).size===s.claimed.length)};\nstate=valid(state)?migrate(state):fresh();\nfunction stockCap(){return 100+state.warehouse*100}\nfunction tick(seconds){let blocked=false;for(let t=0;t<seconds;t++){if(state.workers){state.workerTimer++;if(state.workerTimer>=8){state.workerTimer=0;state.raw=Math.min(stockCap(),state.raw+state.workers)}}if(state.workshop){state.factoryTimer++;if(state.factoryTimer>=20){state.factoryTimer=0;const n=Math.min(state.workshop,Math.floor(state.raw/5));state.raw-=n*5;state.bricks+=n;state.produced+=n}}if(state.manager&&state.bricks){const n=state.bricks;state.coins+=n*20;state.sold+=n*20;state.bricks=0}}}\nfunction advance(){const now=Date.now(),secs=Math.min(7200,Math.max(0,Math.floor((now-state.lastTick)/1000)));if(secs)tick(secs);state.lastTick=now-(secs<7200?Math.max(0,(now-state.lastTick)%1000):0);return secs}\nconst away=advance();if(away>=60&&state.workers)message(\'다시 오셨군요! 최대 2시간의 작업을 정산했어요. 광산 경영에서 생산물을 확인하세요.\');\nsave=function(){advance();baseSave()};\nhud=function(){baseHud();$(\'business\').textContent=\'⛏ 채굴력 \'+power()+\' · 👷 작업자 \'+state.workers+\'명 · 원석 \'+state.raw+\'/\'+stockCap()+\' · 벽돌 \'+state.bricks+\'개\'+(state.manager?\' · 자동 판매 ON\':\'\');};\nfunction transaction(fn){advance();fn();save();hud();}\nfunction spend(price,fn){if(state.coins<price)return;transaction(()=>{state.coins-=price;fn()});openPanel(panelKind)}\nfunction rowsPanel(kind,title,description){panelKind=kind;$(\'panelTitle\').textContent=title;const b=$(\'panelBody\');b.replaceChildren();const p=document.createElement(\'p\');p.textContent=description;b.append(p);return (title,label,fn,disabled=false)=>{const r=document.createElement(\'div\');r.className=\'row\';const d=document.createElement(\'div\');d.textContent=title;const btn=document.createElement(\'button\');btn.textContent=label;btn.disabled=disabled;btn.onclick=fn;r.append(d,btn);b.append(r)}}\nfunction showDialog(){if(!$(\'panel\').open)$(\'panel\').showModal();held={}}\nfunction order(){const i=state.ordersDone;return {n:10+5*(i%5),brick:i%3===2,reward:60+i*15}}\nconst achievements=[{name:\'첫 광부\',desc:\'광석 10개 채굴\',done:()=>state.mined>=10,reward:35},{name:\'금빛 곡괭이\',desc:\'채굴 숙련도 3 달성\',done:()=>state.skill>=3,reward:80},{name:\'우리 회사 첫 직원\',desc:\'작업자 1명 고용\',done:()=>state.workers>=1,reward:50},{name:\'돌에서 벽돌로\',desc:\'벽돌 10개 생산\',done:()=>state.produced>=10,reward:120},{name:\'단골 거래처\',desc:\'납품 주문 3회 완료\',done:()=>state.ordersDone>=3,reward:150},{name:\'깊은 곳의 개척자\',desc:\'지하 5층 도달\',done:()=>state.floor>=5,reward:200}];\nopenPanel=function(kind){advance();if(kind===\'shop\'||kind===\'skills\'){basePanel(kind);return}let row;if(kind===\'manage\'){row=rowsPanel(kind,\'작은 광산 주식회사\',\'작업자 → 원석 창고 → 가공소 → 벽돌 판매. 작업자는 별도 채석장에서 일하며 플레이어 광석은 소모하지 않아요. 접속하지 않아도 최대 2시간 생산합니다.\');let price=80+state.workers*60;row(\'👷 작업자 \'+state.workers+\'/20명 · 8초마다 1인당 원석 1개\',price+\'코인 · 고용\',()=>spend(price,()=>state.workers++),state.workers>=20||state.coins<price);const fprice=150+state.workshop*120;row(\'🏭 가공소 Lv.\'+state.workshop+\'/10 · 20초마다 레벨당 원석 5개 → 벽돌 1개\',fprice+\'코인 · 건설 / 증설\',()=>spend(fprice,()=>state.workshop++),state.workshop>=10||state.coins<fprice);const wprice=70+state.warehouse*60;row(\'📦 원석 창고 \'+state.raw+\'/\'+stockCap()+\' · 가득 차면 채집 중단\',wprice+\'코인 · 용량 +100\',()=>spend(wprice,()=>state.warehouse++),state.warehouse>=10||state.coins<wprice);row(\'🧑\u200d💼 판매 매니저 · 벽돌 자동 판매 (고용 후 벽돌 납품은 자동으로 돌 주문으로 변경)\',state.manager?\'고용 완료\':\'300코인 · 고용\',()=>spend(300,()=>state.manager=1),!!state.manager||state.coins<300);row(\'보관 원석 \'+state.raw+\'개 · 개당 2코인\',\'원석 전부 판매\',()=>{transaction(()=>{state.coins+=state.raw*2;state.sold+=state.raw*2;state.raw=0});openPanel(kind)},!state.raw);row(\'보관 벽돌 \'+state.bricks+\'개 · 개당 20코인\',\'벽돌 전부 판매\',()=>{transaction(()=>{state.coins+=state.bricks*20;state.sold+=state.bricks*20;state.bricks=0});openPanel(kind)},!state.bricks);row(\'가공용 원석은 별도 창고에 보관합니다.\',\'가방 돌 5개 → 창고 원석 5개\',()=>{transaction(()=>{if(state.stone>=5&&state.raw+5<=stockCap()){state.stone-=5;state.raw+=5}});openPanel(kind)},state.stone<5||state.raw+5>stockCap());}\nelse if(kind===\'orders\'){const o=order();o.brick=o.brick&&!state.manager;const key=o.brick?\'bricks\':\'stone\';row=rowsPanel(kind,\'마을 납품 게시판\',\'시간 제한 없는 주문입니다. 기본 판매보다 보상이 높고, 주문을 완료하면 다음 주문이 열려요.\');row(\'주문 #\'+(state.ordersDone+1)+\' · \'+(o.brick?\'벽돌\':\'가방 속 돌\')+\' \'+o.n+\'개 (보유 \'+state[key]+\')\',o.reward+\'코인 + 금 1개 · 납품\',()=>{transaction(()=>{if(state[key]>=o.n){state[key]-=o.n;state.coins+=o.reward;state.gold++;state.ordersDone++}});openPanel(kind)},state[key]<o.n);}\nelse if(kind===\'goals\'){row=rowsPanel(kind,\'작은 목표, 큰 광산\',\'추천 순서: 돌 10개 캐기 → 첫 납품 → 직원 고용 → 가공소 건설. 업적 보상은 한 번만 받을 수 있습니다.\');achievements.forEach((a,i)=>{const claimed=state.claimed.includes(i);row(a.name+\' · \'+a.desc,claimed?\'보상 수령 완료\':a.reward+\'코인 · 보상 받기\',()=>{if(!a.done()||state.claimed.includes(i))return;transaction(()=>{state.claimed.push(i);state.coins+=a.reward});openPanel(kind)},claimed||!a.done())});row(\'누적 채굴 \'+state.mined+\'개 · 생산 벽돌 \'+state.produced+\'개 · 납품 \'+state.ordersDone+\'회\',\'닫기\',closePanel);}if(kind===\'manage\')row(\'생산은 창을 열어 둔 동안에도 계속됩니다.\',\'재고 / 구매 버튼 새로고침\',()=>openPanel(kind));showDialog();hud();};\n$(\'manage\').onclick=()=>openPanel(\'manage\');$(\'orders\').onclick=()=>openPanel(\'orders\');$(\'goals\').onclick=()=>openPanel(\'goals\');\n$(\'newMine\').onclick=()=>{if(state.zone!==\'mine\'||state.floor>=1000)return;const price=20*state.floor;if(state.coins<price){message(\'다음 층 굴착에는 \'+price+\'코인이 필요해요. 돌 판매나 납품으로 모아보세요.\');return}if(!confirm(price+\'코인을 내고 다음 층을 굴착할까요? 현재 광석은 교체됩니다.\'))return;transaction(()=>{state.coins-=price;state.floor++;state.map=newMap();state.x=9;state.y=2});message(\'지하 \'+state.floor+\'층 개방! 금 산출량은 3층마다 늘어납니다.\')};\n// Exhausted mines can be regenerated for free at the same depth.\nconst survey=document.createElement(\'button\');survey.textContent=\'현재 층 다시 탐사\';survey.onclick=()=>{if(state.zone!==\'mine\'){message(\'광산 안에서 사용하세요.\');return}if(!confirm(\'현재 층의 남은 광석을 새로 배치할까요? 비용은 없습니다.\'))return;state.map=newMap();state.x=9;state.y=2;save();hud()};$(\'newMine\').parentNode.append(survey);\n$(\'import\').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>200000)throw Error();const data=JSON.parse(await file.text());if(!valid(data))throw Error();state=migrate(data);advance();save();hud();message(\'저장한 광산을 불러왔어요. 이전 버전 저장도 이어서 플레이할 수 있어요.\')}catch(err){message(\'올바른 GOLDROOT 저장 파일이 아닙니다.\')}e.target.value=\'\'};\nsetInterval(()=>{advance();hud()},1000);\n// Hand-authored pixel sprite. Palette and silhouette are original.\nconst spriteFront=[\n\'.....OOOOOO.....\',\'...OOYYYYYYOO...\',\'..OYYYYYYYYYYO..\',\'..OYYYWHWYYYYO..\',\'.OYYYYWHWYYYYYO.\',\'.OOOOOOOOOOOOOO.\',\'..OTTTTTTTTTTO..\',\'..OTDTTTTTDTTO..\',\'..OTDTTTTTDTTO..\',\'..OTTRTTTRTTTO..\',\'...OTTTTTTTTO...\',\'....OOOMMOOO....\',\'...OCCMMCCCO....\',\'..OTCCBBCCCTO...\',\'..OTTBBBBBTTO...\',\'...OOBBBBBOO....\',\'....OBBOBBO.....\',\'...OOBBOBBOO....\',\'...OOOOOOOOO....\'];\nfunction drawMiner(x,y,time,dir,moving,hit,scale=2){const pal={O:\'#283746\',Y:\'#f4c654\',W:\'#fff2b4\',H:\'#ffffff\',T:\'#ffdab5\',D:\'#283746\',R:\'#f08f94\',M:\'#f2b342\',C:\'#60bcbb\',B:\'#447b9e\'};ctx.save();ctx.translate(Math.round(x-16*scale/2),Math.round(y-12*scale-(moving?Math.sin(time*.025)*2:0)));if(dir===\'left\'){ctx.translate(16*scale,0);ctx.scale(-1,1)}const back=dir===\'up\';spriteFront.forEach((line,yy)=>[...line].forEach((c,xx)=>{if(c!==\'.\'){if(back&&yy>=6&&yy<=10)c=\'Y\';rect(xx*scale,yy*scale,scale,scale,pal[c])}}));if(back){rect(4*scale,12*scale,8*scale,4*scale,\'#ab7656\');rect(5*scale,13*scale,6*scale,2*scale,\'#dca76b\')}ctx.translate(15*scale,12*scale);ctx.rotate(-.5+hit*1.5);rect(0,-5*scale,2*scale,11*scale,\'#714c38\');rect(-4*scale,-7*scale,10*scale,2*scale,\'#293b49\');rect(-3*scale,-7*scale,8*scale,scale,\'#d8edf0\');rect(5*scale,-6*scale,scale,3*scale,\'#91b6c8\');ctx.restore()}\nfunction drawBusiness(tile,now){if(state.zone!==\'surface\')return;if(state.workers){drawMiner(3*tile,10*tile,now,\'right\',.5,Math.sin(now*.006)>0?.7:0,1.5);label(\'작업자 \'+state.workers+\'명\',3*tile,10*tile+28,\'#cbe1d4\',10)}if(state.workshop){rect(7*tile,11*tile,tile,27,\'#698c93\');rect(7*tile+5,11*tile+7,12,14,\'#172c31\');rect(7*tile+9,11*tile+11,5,7,\'#ffc879\');label(\'가공소 Lv.\'+state.workshop,7.5*tile,11*tile-7,\'#d4e3d5\',10)}if(state.manager){drawMiner(15*tile,10*tile,now,\'down\',0,0,1.5);label(\'판매 매니저\',15*tile,10*tile+28,\'#ecd0ad\',10)}}\n\nhud();requestAnimationFrame(frame);\n</script></html>\n'
